use autonavi::AutoNavi;
use egui::*;
use paiagram_core::{Coord, CoordType, WgsProjection};
use serde::{Deserialize, Serialize};
use walkers::sources::OpenStreetMap;
use walkers::{HttpTiles, Map, MapMemory, Projector};

use super::Tile;
use crate::App;
mod autonavi;
mod display_selected_content;
pub(crate) mod gpu_draw;
mod map_content;
mod projection;
mod select_content;
mod viewport;

use projection::XyProjection;

// generated by build.rs
mod graph_intervals {
    include!(concat!(env!("OUT_DIR"), "/graph_intervals.rs"));
}
mod graph_nodes {
    include!(concat!(env!("OUT_DIR"), "/graph_nodes.rs"));
}

#[derive(Serialize, Deserialize, Default)]
#[serde(default)]
pub(crate) struct MapTile {
    map_memory: Option<MapMemory>,
    // cache zone
    #[serde(skip)]
    tiles: Option<HttpTiles>,
    #[serde(skip)]
    trip_icon: Option<TextureHandle>,
}

impl PartialEq for MapTile {
    fn eq(&self, _: &Self) -> bool {
        true
    }
}

impl Tile for MapTile {
    const NAME: &'static str = "Map";
    fn main_display(&mut self, app: &mut App, ui: &mut Ui) {
        puffin::profile_function!();
        Frame::canvas(ui.style())
            .inner_margin(Margin::ZERO)
            .outer_margin(Margin::ZERO)
            .stroke(Stroke::NONE)
            .show(ui, |ui| {
                main_display(self, app, ui);
            });
    }
}

/// MapPlugin runs before [`super::select_content::SelectPlugin`]
pub struct MapPlugin<'a> {
    /// Closure to work around with lifetimes
    pub app: &'a mut App,
    pub trip_icon: TextureId,
}

impl<'a> walkers::Plugin for MapPlugin<'a> {
    fn run(
        self: Box<Self>,
        ui: &mut Ui,
        response: &Response,
        projector: &Projector,
        _map_memory: &MapMemory,
    ) {
        let MapPlugin { app, trip_icon } = *self;
        map_content::render_map_contents(app, trip_icon, ui, response, projector);
        display_selected_content::display_selected_content(app, ui, response, projector);
        select_content::select_map_contents(app, ui, response, projector);
    }
}

fn main_display(tile: &mut MapTile, app: &mut App, ui: &mut Ui) {
    puffin::profile_function!();
    let viewport = ui.available_size();
    let tile_window = Window::new("foo bar")
        .id(ui.scope_id().with("foo bar"))
        .auto_sized()
        .title_bar(false)
        .fixed_pos(ui.clip_rect().shrink(8.0).right_top())
        .pivot(Align2::RIGHT_TOP);
    let mut coord_type = app.world().graph.coord_type;
    tile_window.show(ui.ctx(), |ui| {
        if ui.button("Auto layout").clicked() {
            app.auto_layout();
            // Coordinates changed, so refit the viewport on the next frame.
            tile.map_memory = None;
        }
        if ui.button("Center viewport").clicked()
            && let Some(map_memory) = tile.map_memory.as_mut()
        {
            *map_memory = viewport::fit_viewport_to_nodes(app, viewport);
        }
        ComboBox::from_id_salt("coordinate type and projection")
            .selected_text(coord_type.name())
            .truncate()
            .show_ui(ui, |ui| {
                for option in CoordType::ALL {
                    if ui.selectable_value(&mut coord_type, *option, option.name()).changed() {
                        let _ = app.mutate(|mut world| {
                            world.graph.coord_type = *option;
                            Ok(world)
                        });
                        // Both the tile source and the fitted viewport follow the projection.
                        tile.tiles = None;
                        tile.map_memory = None;
                    }
                }
            });
        ui.label({
            let zoom = tile.map_memory.as_ref().map_or(0.0, |mem| mem.zoom());
            format!("{:.3}", zoom)
        });
    });
    let coord_type = app.world().graph.coord_type;
    let is_autonavi = matches!(coord_type, CoordType::Wgs(WgsProjection::GcjAndMercator));
    if tile.tiles.is_none() {
        let ctx = ui.ctx().clone();
        tile.tiles = Some(if is_autonavi {
            HttpTiles::new(AutoNavi, ctx)
        } else {
            HttpTiles::new(OpenStreetMap, ctx)
        });
    }
    let map_memory =
        tile.map_memory.get_or_insert_with(|| viewport::fit_viewport_to_nodes(app, viewport));
    let trip_icon =
        tile.trip_icon.get_or_insert_with(|| map_content::load_trip_icon(ui.ctx())).id();
    let projection = XyProjection;
    let map = Map::new(
        match tile.tiles.as_mut() {
            // map::new wants dyn, thus rebind
            Some(tiles) => Some(tiles),
            None => None,
        },
        map_memory,
        XyProjection::to_position(coord_type.project(Coord::from_wgs84(-123.1139, 49.2612))),
    )
    .with_projection(&projection)
    .with_plugin(MapPlugin { app, trip_icon });
    ui.add(map);
}
